1	import type {AddressInfo} from 'node:net';
2	import {WebSocket} from 'ws';
3	import type {Express} from 'express';
4	import {createServer} from './createServer.js';
5	import type {HalServer, HalServerOptions} from './createServer.js';
6	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
7	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
8	import type {MessageChunk} from '../types/ai.js';
9	import type {ChatSession} from '../types/session.js';
10	import type {SessionStore} from '../types/sessionStore.js';
11	import type {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
12	
13	// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.
14	
15	const servers: HalServer[] = [];
16	const clients: WebSocket[] = [];
17	
18	/** Resolves once `check` holds, polling while a socket answer closes or a close propagates. */
19	export async function eventually(check: () => boolean): Promise<void> {
20	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
21	}
22	
23	/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
24	export const answeringOrchestrator: ChatOrchestrator = {
25	  processMessage: async () => 'hi',
26	  async *processMessageStream(): AsyncGenerator<MessageChunk> {
27	    yield {type: 'text', text: 'hi'};
28	    yield {type: 'stop', stopReason: 'end_turn'};
29	  },
30	};
31	
32	/** Starts an engine on an ephemeral port and returns the URL a client should open. */
33	export async function startEngine(
34	  sessionStore: SessionStore,
35	  onDisconnect?: (sessionId: string) => void
36	): Promise<string> {
37	  const {url} = await startEngineWith({sessionStore, onDisconnect});
38	  return url;
39	}
40	
41	/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
42	export async function startEngineWith(
43	  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
44	): Promise<{url: string; hal: HalServer}> {
45	  const hal = createServer({
46	    app: (() => undefined) as unknown as Express,
47	    wsAuth: async () => ({id: 'u1'}),
48	    orchestrator: answeringOrchestrator,
49	    ...options,
50	  });
51	  await hal.start(0);
52	  servers.push(hal);
53	  const {port} = hal.server.address() as AddressInfo;
54	  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
55	}
56	
57	/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
58	export function connectClient(url: string, token = 't'): WebSocket {
59	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
60	  clients.push(client);
61	  return client;
62	}
63	
64	/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
65	export function deferred(): {until: Promise<void>; release: () => void} {
66	  let release = (): void => undefined;
67	  const until = new Promise<void>(resolve => {
68	    release = resolve;
69	  });
70	  return {until, release};
71	}
72	
73	/** Resolves with every frame type seen up to and including the first `until` frame. */
74	export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
75	  const seen: string[] = [];
76	  return new Promise<string[]>(resolve => {
77	    client.on('message', raw => {
78	      const {type} = JSON.parse(String(raw)) as {type: string};
79	      seen.push(type);
80	      if (type === until) resolve(seen);
81	    });
82	  });
83	}
84	
85	/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
86	export function askOnOpen(
87	  url: string,
88	  {until = 'stream_end', token}: {until?: string; token?: string} = {}
89	): {client: WebSocket; finished: Promise<string[]>} {
90	  const client = connectClient(url, token);
91	  const finished = framesUntil(client, until);
92	  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
93	  return {client, finished};
94	}
95	
96	/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
97	export function announcedId(client: WebSocket): () => string {
98	  let sessionId = '';
99	  client.on('message', raw => {
100	    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
101	    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
102	  });
103	  return () => sessionId;
104	}
105	
106	/** Tears every socket and server down, so a red test reports instead of hanging the run. */
107	export async function stopEngines(): Promise<void> {
108	  for (const client of clients.splice(0)) client.terminate();
109	  // Each server sees its sockets close before it stops, so no close lands after the next suite's logger is in place.
110	  for (const hal of servers.splice(0)) {
111	    await eventually(() => hal.wss.clients.size === 0);
112	    await hal.stop();
113	  }
114	}
115	
116	/** Asks the shared teardown to stop a server a suite started by hand. */
117	export function trackServer(hal: HalServer): void {
118	  servers.push(hal);
119	}
120	
121	/** A store with only the required members, so an optional one can be added, replaced or left out per test. */
122	export function delegatingTo(inner: InMemorySessionStore): SessionStore {
123	  return {
124	    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
125	    get: sessionId => inner.get(sessionId),
126	    delete: sessionId => inner.delete(sessionId),
127	    count: () => inner.count(),
128	    clear: () => inner.clear(),
129	  };
130	}
131	
132	/** Every list_sessions frame the validator refuses, so the unit and the socket suites reject the same wire. */
133	export const malformedListSessionsFrames: object[] = [
134	  {type: 'list_sessions', limit: 'ten'},
135	  {type: 'list_sessions', limit: -1},
136	  {type: 'list_sessions', limit: 1.5},
137	  {type: 'list_sessions', before: 'not-an-object'},
138	  {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
139	  {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
140	  {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
141	  {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
142	  {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z'}},
143	  {type: 'list_sessions', before: {sessionId: 's1'}},
