  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Failure test.'}), registry);
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  await createMessageHandler(orchestrator)(ws, session, userMessage('hello'));
  return wire(sent);
}

// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}

describe('the conversation list', () => {
  const errors = captureErrors();
  const CURSOR = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
  const summaries: SessionSummary[] = [
    {
      sessionId: 's2',
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-01T00:02:00.000Z'),
      entryCount: 4,
    },
  ];

  // A store with only the five required members, so listFor can be present, absent or failing per test.
  const listHarness = (listFor?: SessionStore['listFor']) => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const store: SessionStore = {
      create: async () => session,
      get: async () => session,
      delete: async () => true,
      count: async () => 1,
      clear: async () => undefined,
      listFor,
    };
    const handle = createMessageHandler({} as unknown as ChatOrchestrator, store);
    return {ws, session, sent, ask: () => handle(ws, session, {type: 'list_sessions', limit: 10, before: CURSOR})};
  };

  it("answers with the socket user's own list, its times as ISO strings, and the window the frame sent", async () => {
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const {sent, ask} = listHarness((userId, options) => {
      seen.push({userId, options});
      return summaries;
    });

    await ask();

    expect({asked: seen, frames: sent}).toEqual({
      asked: [{userId: 'u1', options: {limit: 10, before: CURSOR}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers a store that implements no listFor with an empty list, and a failing one with one SERVER_ERROR and a ws log', async () => {
    const {sent: unimplemented, ask: askUnimplemented} = listHarness();
    const {sent: failed, ask: askFailing} = listHarness(() => Promise.reject(new Error('database offline')));

    await askUnimplemented();
    await askFailing();

    expect({unimplemented, failed, logged: errors}).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}],
      logged: [{category: 'ws', message: expect.any(String), sessionId: 's1', userId: 'u1', error: 'database offline'}],
    });
  });

  it('answers while a turn is still streaming, without waiting on the session lock', async () => {
    const gate = deferred();
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const store: SessionStore = {
      create: async () => session,
      get: async () => session,
      delete: async () => true,
      count: async () => 1,
      clear: async () => undefined,
      listFor: () => summaries,
    };
    const orchestrator = {
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield text('half');
        await gate.until;
        yield STOP;
      },
    } as unknown as ChatOrchestrator;
    const handle = createMessageHandler(orchestrator, store);

    const turn = handle(ws, session, userMessage('hello'));
    await afterPendingWork();
    await handle(ws, session, {type: 'list_sessions', limit: 10});
    gate.release();
    await turn;

    expect(sent.map(frame => frame.type)).toEqual([
      'entry_upsert',
      'entry_upsert',
      'entry_delta',
      'session_list',
      'entry_commit',
      'stream_end',
    ]);
  });
});

