+    gate.release();
+    await turn;
+
+    expect(sent.map(frame => frame.type)).toEqual([
+      'entry_upsert',
+      'entry_upsert',
+      'entry_delta',
+      'session_list',
+      'entry_commit',
+      'stream_end',
+    ]);
+  });
+});
