const fs=require('fs');
const txt=fs.readFileSync('coverage/lcov.info','utf8');
const files=txt.split('end_of_record');
let g={s:0,sh:0,b:0,bh:0,f:0,fh:0,l:0,lh:0};
const rows=[];
for(const blk of files){
  const sf=/^SF:(.+)$/m.exec(blk); if(!sf) continue;
  const p=sf[1];
  const LF=+(/LF:(\d+)/.exec(blk)||[0,0])[1], LH=+(/LH:(\d+)/.exec(blk)||[0,0])[1];
  const FNF=+(/FNF:(\d+)/.exec(blk)||[0,0])[1], FNH=+(/FNH:(\d+)/.exec(blk)||[0,0])[1];
  const BRF=+(/BRF:(\d+)/.exec(blk)||[0,0])[1], BRH=+(/BRH:(\d+)/.exec(blk)||[0,0])[1];
  const nStmt=(blk.match(/^DA:\d+,\d+/gm)||[]).length;
  const hitStmt=(blk.match(/^DA:\d+,[1-9]/gm)||[]).length;
  g.s+=nStmt;g.sh+=hitStmt;g.b+=BRF;g.bh+=BRH;g.f+=FNF;g.fh+=FNH;g.l+=LF;g.lh+=LH;
  if(LF>LH) rows.push(p+' lines '+LH+'/'+LF);
}
const pct=(a,b)=>b? (100*a/b).toFixed(2):'0';
console.log('GLOBAL statements',pct(g.sh,g.s),'branches',pct(g.bh,g.b),'functions',pct(g.fh,g.f),'lines',pct(g.lh,g.l));
console.log('floors: statements 91.3 branches 83.55 functions 89.79 lines 91.92');
console.log('files missing line coverage:'); rows.forEach(r=>console.log(' ',r));
"

